/*
 Problem: 3622. Check Divisibility by Digit Sum and Product
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 7.7 MB (94.62%)
 Tags: Math
*/
class Solution {
public:
    bool checkDivisibility(int n) {
        int original = n;
        int sum = 0, product = 1;

        while (n > 0) {
            int digit = n % 10;

            sum += digit;
            product *= digit;

            n /= 10;
        }

        return original % (sum + product) == 0;
    }
};
